components.customConditional:
if (data.applicationId) {
  // Remove all delete file buttons when application is submitted
  document.querySelectorAll("i[ref=\"removeLink\"]").forEach(function(el) { el.style.display = 'none'; });
  // Replace download links with XHR handlers for authenticated download (guarded to run once per link)
  var els = document.getElementsByTagName("a");
  for (var i = 0, l = els.length; i < l; i++) {
    var el = els[i];
    if (el.href && el.href.includes('/api/v1/files/') && !el.dataset.xhrBound) {
      (function(link) {
        var newLink = document.createElement("a");
        newLink.innerHTML = link.innerHTML;
        newLink.style.color = "#0000FF";
        newLink.style.cursor = "pointer";
        newLink.aHref = link.href;
        newLink.dataset.xhrBound = "1";
        newLink.onclick = function() {
          var oReq = new XMLHttpRequest();
          oReq.open("GET", newLink.aHref);
          var dlToken = localStorage.getItem('AUTH_TOKEN');
          if (dlToken) oReq.setRequestHeader('Authorization', 'Bearer ' + dlToken);
          oReq.responseType = 'blob';
          oReq.onload = function(e) {
            var blob = e.currentTarget.response;
            var fileName = newLink.aHref.split("?originalName=")[1];
            var a = document.createElement('a');
            a.href = window.URL.createObjectURL(blob);
            a.download = fileName;
            a.dispatchEvent(new MouseEvent('click'));
          };
          oReq.send();
        };
        link.parentNode.replaceChild(newLink, link);
      })(el);
    }
  }
} else {
  // Remove delete buttons for public view (remove endpoint requires auth)
  document.querySelectorAll("i[ref=\"removeLink\"]").forEach(function(el) { el.style.display = 'none'; });
  // Remove file download links for public view
  var links = document.querySelectorAll("a[ref='fileLink']");
  for (var i = 0; i < links.length; i++) {
    var fileName = links[i].innerText.split("\n").pop();
    var linkParent = links[i].parentNode;
    linkParent.removeChild(links[i]);
    linkParent.innerHTML = fileName;
  }
}
show = true;

