    // 1. Log the error for quick debugging
    console.error('Custom Save Error:', error);

    // 2. Normalize the error message depending on Form.io's API response structure
    let errorMessage = 'An error occurred while saving the form.';
    if (typeof error === 'string') {
      errorMessage = error;
    } else if (error && error.message) {
      errorMessage = error.message;
    } else if (Array.isArray(error)) {
      // Form.io often returns an array of validation error objects
      errorMessage = error.map(err => err.message || err).join(', ');
    }

    // 3. Notify the user interface using Form.io's native alert system
    if (typeof form.setAlert === 'function') {
      form.setAlert('danger', `Save Failed: ${errorMessage}`);
    }

